import { z } from 'zod';

export interface SessionWorktree {
  path: string;
  branch: string;
  recordedTargetBranch: string;
}

export const SessionWorktreeSchema = z.object({
  path: z.string(),
  branch: z.string(),
  recordedTargetBranch: z.string(),
});

export function resolveUseWorktree(
  card: boolean | null,
  global: boolean,
): boolean {
  return card ?? global;
}

/**
 * The two turns Ship can drive on the user's behalf. They are ordinary
 * agent turns — they appear in the card's transcript like any other, which
 * is deliberate: the user must be able to read what the agent committed or
 * how it resolved a conflict.
 */
export const SHIP_PREPARE_PROMPT =
  "Prepare this card's worktree for Ship. Review the current changes, run the relevant tests, and commit the intended changes. Do not push. Leave git status clean. If there is nothing to commit, say so.";

export const SHIP_CONFLICT_PROMPT =
  'You are finishing a git merge in this worktree that the app started for Ship. Resolve every conflict, complete the merge with a commit, and do not push. Do not change files outside this working directory. Do not abort the merge.';

export function featureBranchFor(cardId: string): string {
  return `kanban/${cardId}`;
}

export function truncateBranch(name: string, maxChars = 32): string {
  if (name.length <= maxChars) return name;
  return name.slice(0, maxChars - 1) + '…';
}

export type ShipHead =
  | { kind: 'branch'; name: string }
  | { kind: 'detached' };

export type ShipChooserPlan =
  | { kind: 'direct'; destination: string }
  | { kind: 'choose'; recorded: string; current: string }
  | { kind: 'recorded-missing'; current: string }
  | { kind: 'detached-with-recorded'; recorded: string }
  | { kind: 'blocked'; message: string };

export function planShipChooser(input: {
  recorded: string;
  current: ShipHead;
  recordedExists: boolean;
}): ShipChooserPlan {
  const { recorded, current, recordedExists } = input;

  if (current.kind === 'detached') {
    if (recordedExists) {
      return { kind: 'detached-with-recorded', recorded };
    }
    return {
      kind: 'blocked',
      message:
        'Cannot ship: the original branch is gone and HEAD is detached.',
    };
  }

  if (current.name === recorded) {
    return { kind: 'direct', destination: recorded };
  }

  if (recordedExists) {
    return { kind: 'choose', recorded, current: current.name };
  }

  return { kind: 'recorded-missing', current: current.name };
}
